// ─── Main Component ─────────────────────────────────────────────────────────────

// ─── Seeded PRNG (mulberry32) — deterministic per seed, varied per month/day ──
function mulberry32(seed) {
  return function() {
    seed |= 0; seed = seed + 0x6D2B79F5 | 0;
    let t = Math.imul(seed ^ seed >>> 15, 1 | seed);
    t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;
    return ((t ^ t >>> 14) >>> 0) / 4294967296;
  };
}
function isWorkingDay(dateStr) {
  const d = new Date(dateStr + "T00:00:00");
  const dow = d.getDay();
  return dow >= 1 && dow <= 5;
}
function monthSeed(year, month) { return year * 100 + month + 7919; }
function daySeed(dateStr) {
  let h = 0;
  for (let i = 0; i < dateStr.length; i++) {
    h = (Math.imul(31, h) + dateStr.charCodeAt(i)) | 0;
  }
  return h;
}
function getBookedDaysForMonth(year, month) {
  const rand = mulberry32(monthSeed(year, month));
  const booked = new Set();
  const daysInMonth = new Date(year, month, 0).getDate();
  const workingDays = [];
  for (let d = 1; d <= daysInMonth; d++) {
    const dateStr = `${year}-${String(month).padStart(2,"0")}-${String(d).padStart(2,"0")}`;
    if (isWorkingDay(dateStr)) workingDays.push(d);
  }
  const targetBooked = Math.round(workingDays.length * 0.3);
  const shuffled = [...workingDays].sort(() => rand() - 0.5);
  shuffled.slice(0, targetBooked).forEach(d => booked.add(d));
  return booked;
}
function getBookedTimesForDate(dateStr) {
  const rand = mulberry32(daySeed(dateStr));
  const booked = new Set();
  const shuffled = [...TIMES].sort(() => rand() - 0.5);
  const targetBooked = Math.round(TIMES.length * 0.30);
  shuffled.slice(0, targetBooked).forEach(t => booked.add(t));
  return booked;
}
function isDayFullyBooked(dateStr) {
  const d = new Date(dateStr + "T00:00:00");
  const year = d.getFullYear(), month = d.getMonth() + 1, day = d.getDate();
  return getBookedDaysForMonth(year, month).has(day);
}

